import test from 'node:test';import assert from 'node:assert/strict';
import {Battle,makeEnemy} from '../battle.js?v=5.6.0';import {defaultHero} from '../mako.js';import {dressEncounter,shellFor,materialPool,MATERIALS} from '../environment-shells.js';import {applySupply} from '../repertoire.js?v=5.6.0';
function setup(material){const h=defaultHero(0,8),e=makeEnemy('predator',8);e.hp=e.maxHp=10000;e.shell=shellFor(material);h.x=0;h.y=0;e.x=3;e.y=0;return new Battle({heroes:[h],enemies:[e],chapter:1});}
function hit(b,core){return b.damage(b.heroes[0],b.enemies[0],100,{core,physical:core==='physical'}).damage;}
test('formation policy is bounded, deterministic and excludes tutorials, rivals and bosses',()=>{for(let serial=1;serial<31;serial++)for(let count=1;count<=5;count++){const a=Array.from({length:count},(_,i)=>makeEnemy('predator',5,i)),b=structuredClone(a),c={key:'river',encounterSerial:serial,tags:['wet']};dressEncounter(a,c,5);dressEncounter(b,c,5);assert.deepEqual(a,b);assert.equal(a.filter(e=>e.shell).length,count===1?(serial%3===1?1:0):Math.ceil(count/2));}for(const context of [{friendly:true},{tutorial:true}]){const a=[makeEnemy('predator',5)];dressEncounter(a,context,5);assert.equal(a[0].shell,undefined);}const boss=makeEnemy('boss',8,0,true);dressEncounter([boss],{},8);assert.equal(boss.shell,undefined);});
test('habitat contributes real local materials',()=>{assert.ok(materialPool(['wet']).includes('reed'));assert.ok(materialPool(['cold']).includes('rime'));assert.ok(materialPool(['heat']).includes('ash'));});
test('clay action order changes actual damage and exposes the creature',()=>{const a=setup('clay'),b=setup('clay');const ordered=['tide','frost','physical'].reduce((s,c)=>s+hit(a,c),0),reverse=['physical','frost','tide'].reduce((s,c)=>s+hit(b,c),0);assert.ok(ordered>reverse);assert.equal(a.enemies[0].shell.integrity,0);assert.ok(a.enemies[0].status.exposed);assert.ok(b.enemies[0].shell.integrity>0);});
test('dry heat fires clay, water then thermal-fractures it; reeds char before Gale strips',()=>{const a=setup('clay');hit(a,'flame');assert.ok(a.enemies[0].shell.fired);hit(a,'tide');assert.ok(a.enemies[0].shell.integrity<.2);const b=setup('reed');hit(b,'flame');hit(b,'gale');assert.equal(b.enemies[0].shell.integrity,0);});
test('ash washes, rime melts, mineral charging enables ground fracture',()=>{for(const [material,cores] of [['ash',['tide']],['rime',['flame']],['mineral',['volt','earth']]]){const b=setup(material);cores.forEach(c=>hit(b,c));assert.equal(b.enemies[0].shell.integrity,0,material);}});
test('every material can be defeated with basic attacks within five hits without magical gates',()=>{for(const m of Object.keys(MATERIALS)){const b=setup(m);for(let i=0;i<5;i++)assert.ok(hit(b,'physical')>=60);assert.equal(b.enemies[0].shell.integrity,0,m);}});
test('shell condition persists through battle save and older battles need no shell',()=>{const b=setup('clay');hit(b,'tide');const copy=setup('ash');copy.restore(b.snapshot());assert.deepEqual(copy.enemies[0].shell,b.enemies[0].shell);hit(copy,'frost');hit(copy,'physical');assert.equal(copy.enemies[0].shell.integrity,0);delete copy.enemies[0].shell;assert.ok(hit(copy,'earth')>0);});
test('supplies trigger the same material rules and secondary effects cannot recurse shell reactions',()=>{const b=setup('ash');b.heroes[0].atb=1;assert.ok(applySupply(b,{rainJar:1},'rainJar',b.heroes[0],b.enemies[0]));assert.equal(b.enemies[0].shell.integrity,0);const c=setup('mineral');c.damage(c.heroes[0],c.enemies[0],30,{core:'volt',secondary:true});assert.equal(c.enemies[0].shell.charged,false);});
